    cols=[c for c in range(len(grid[0])) if any(grid[r][c]==5 for r in rows)]
    # Process separate rectangular frames independently.
    seen=set()
    for r in rows:
        for c in cols:
            if grid[r][c]!=5 or (r,c) in seen: continue
            stack=[(r,c)]; comp=[]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    a,b=q
                    if 0<=a<len(grid) and 0<=b<len(grid[0]) and grid[a][b]==5 and q not in seen: seen.add(q); stack.append(q)
            y0=min(y for y,x in comp); y1=max(y for y,x in comp); x0=min(x for y,x in comp); x1=max(x for y,x in comp)
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    if grid[y][x]==0: out[y][x]=2
